# Acronym Expansion Engine - runnable demo (JAH-ATK165-000001)
import re
from collections import Counter
RANK = 1
SIG = False
DOCS = ['The National Aeronautics and Space Administration (NASA) launched. NASA plans more.', 'A temporary restraining order (TRO) was filed. The TRO hearing is Monday.']
cands = {}
pat1 = re.compile(r"([A-Z][A-Za-z ]+?)\s*\(([A-Z]{2,})\)")
pat2 = re.compile(r"\b([A-Z]{2,})\b\s*\(\s*([A-Z][A-Za-z ]+?)\)")
for d in DOCS:
    for exp, acr in pat1.findall(d) + [(e, a) for a, e in pat2.findall(d)]:
        cands.setdefault(acr.strip(), Counter())[exp.strip()] += 1
print("mined candidates:")
for acr, exps in cands.items():
    print(" ", acr, "->", dict(exps))
TEST = "The TRO was denied while the MSJ was granted."
if RANK >= 2:
    found = re.findall(r"\b([A-Z]{2,})\b", TEST)
    for f in found:
        if f in cands: print("expand %-4s -> %s" % (f, cands[f].most_common(1)[0][0]))
        else: print("expand %-4s -> UNRESOLVED" % f)
if RANK >= 3:
    print("total pairs mined:", sum(sum(c.values()) for c in cands.values()))
if SIG:
    print("Signature lineage stamp: JAH-SIG-ACR-" + "JAH-ATK165-000001")
print("record:", "JAH-ATK165-000001", "OK")

